const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define locations
  const cuyuniPoint = ee.Geometry.Point([-58.628264, 6.437929]);
  const confluencePoint = ee.Geometry.Point([-58.606792, 6.407305]);

  // Buffer points for sampling
  const cuyuniRegion = cuyuniPoint.buffer(100);
  const confluenceRegion = confluencePoint.buffer(100);

  // 2. Define date range (±3 days to increase chances)
  const startDate = '2023-08-13';
  const endDate = '2023-08-19';

  console.log('Searching for imagery...');

  // 3. Try Sentinel-2 first
  let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(cuyuniPoint)
    .filterDate(startDate, endDate)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 50));

  let size = await collection.size().getInfo();
  console.log(`Sentinel-2 images found: ${size}`);

  // Fallback to Landsat if no Sentinel-2
  if (size === 0) {
    console.log('Trying Landsat 8/9...');
    collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .merge(ee.ImageCollection('LANDSAT/LC09/C02/T1_L2'))
      .filterBounds(cuyuniPoint)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUD_COVER', 50));

    size = await collection.size().getInfo();
    console.log(`Landsat images found: ${size}`);
  }

  if (size === 0) {
    console.log('No images found in date range.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Select best image and mask clouds
  let image;
  if (collection.first().bandNames().getInfo().includes('B4')) {
    // Sentinel-2
    image = collection.sort('CLOUDY_PIXEL_PERCENTAGE').first();
    const qa = image.select('QA60');
    const cloudMask = qa.bitwiseAnd(1 << 10).eq(0)
      .and(qa.bitwiseAnd(1 << 11).eq(0));
    image = image.updateMask(cloudMask).select(['B2', 'B3', 'B4']);
  } else {
    // Landsat
    image = collection.sort('CLOUD_COVER').first();
    const qa = image.select('QA_PIXEL');
    const cloudMask = qa.bitwiseAnd(1 << 3).eq(0)
      .and(qa.bitwiseAnd(1 << 4).eq(0));
    image = image.updateMask(cloudMask)
      .select(['SR_B2', 'SR_B3', 'SR_B4'], ['B2', 'B3', 'B4']);
  }

  // 5. Calculate brightness (mean of visible bands)
  const brightness = image.expression('(B2 + B3 + B4) / 3', {
    'B2': image.select('B2'),
    'B3': image.select('B3'),
    'B4': image.select('B4')
  });

  // 6. Sample both locations
  const cuyuniStats = await brightness.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: cuyuniRegion,
    scale: 30,
    maxPixels: 1e9
  }).getInfo();

  const confluenceStats = await brightness.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: confluenceRegion,
    scale: 30,
    maxPixels: 1e9
  }).getInfo();

  const cuyuniMean = cuyuniStats.mean;
  const cuyuniCount = cuyuniStats.count;
  const confluenceMean = confluenceStats.mean;
  const confluenceCount = confluenceStats.count;

  console.log(`Cuyuni: brightness=${cuyuniMean}, pixels=${cuyuniCount}`);
  console.log(`Confluence: brightness=${confluenceMean}, pixels=${confluenceCount}`);

  // 7. Validate results
  if (cuyuniCount === 0 || confluenceCount === 0) {
    console.log('No valid pixels after cloud masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (cuyuniMean === null || confluenceMean === null || 
      isNaN(cuyuniMean) || isNaN(confluenceMean)) {
    console.log('Calculation failed - invalid values.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 8. Compare brightness
  if (cuyuniMean > confluenceMean) {
    console.log('Cuyuni River is lighter in color.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Cuyuni River is not lighter in color.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
